import { zonedDayStartISO } from '@/lib/localDay';
import { Badge } from '@/components/ui/badge';
import type { TimeFilter } from './telemetryTypes';

export function formatDuration(ms: number) {
  if (ms >= 1000) return `${(ms / 1000).toFixed(1)}s`;
  return `${ms}ms`;
}

export function formatTime(iso: string) {
  return new Date(iso).toLocaleString("pt-BR", {
    hour: "2-digit", minute: "2-digit", second: "2-digit",
    day: "2-digit", month: "2-digit",
  });
}

export function getSeverityBadge(severity: string) {
  switch (severity) {
    case "very_slow":
      return <Badge className="bg-destructive/20 text-destructive border-destructive/30 text-3xs">🔴 Muito Lenta</Badge>;
    case "slow":
      return <Badge className="bg-warning/20 text-warning border-warning/30 text-3xs">🟡 Lenta</Badge>;
    case "error":
      return <Badge className="bg-destructive/20 text-destructive border-destructive/30 text-3xs">❌ Erro</Badge>;
    default:
      return <Badge variant="secondary" className="text-3xs">{severity}</Badge>;
  }
}

/**
 * R2-INF-040: `rows = []` NÃO é sinal de "sistema com bom desempenho".
 *
 * O `queryFn` lança o erro do SDK, mas a página precisa separar o que a tela sabe sobre a
 * CONSULTA (carregando, falhou, vazio, com dados) do que ela conclui sobre o BANCO. Sem
 * isso, a falha de leitura chegava à tabela como lista vazia e a tela anunciava bom
 * desempenho justo quando não havia conseguido medir nada.
 *
 * `stale` é a falha de REFETCH: já havia dados bons em cache e a nova leitura falhou. A
 * tela segue mostrando os últimos números (com aviso de defasagem) em vez de apagá-los ou
 * de apresentá-los como leitura fresca.
 *
 * `loading` vence a ordem: na primeira carga não existe nem medição nem erro concluído.
 */
export type TelemetryViewState = 'loading' | 'error' | 'stale' | 'empty' | 'data';

export function telemetryViewState({
  isLoading,
  isError,
  rowCount,
}: {
  isLoading: boolean;
  isError: boolean;
  rowCount: number;
}): TelemetryViewState {
  if (isLoading) return 'loading';
  if (isError) return rowCount > 0 ? 'stale' : 'error';
  return rowCount > 0 ? 'data' : 'empty';
}

/** Detalhe técnico da falha de leitura (para o admin), nunca uma conclusão de saúde. */
export function telemetryReadFailureDetail(error: unknown): string {
  if (typeof error === 'string' && error) return error;
  if (error && typeof error === 'object') {
    const message = (error as { message?: unknown }).message;
    if (typeof message === 'string' && message) return message;
  }
  return 'A leitura não retornou o detalhe do erro.';
}

export function computeTopOffenders(rows: { rpc_name: string | null; table_name: string | null; duration_ms: number }[]) {
  const tableStats = new Map<string, { count: number; totalMs: number; maxMs: number }>();
  for (const r of rows) {
    const key = r.rpc_name || r.table_name || "unknown";
    const prev = tableStats.get(key) || { count: 0, totalMs: 0, maxMs: 0 };
    tableStats.set(key, {
      count: prev.count + 1,
      totalMs: prev.totalMs + r.duration_ms,
      maxMs: Math.max(prev.maxMs, r.duration_ms),
    });
  }
  return [...tableStats.entries()].sort((a, b) => b[1].count - a[1].count).slice(0, 8);
}

/**
 * Fuso dos recortes por **dia de calendário**.
 *
 * É fixo (e não o do navegador) porque o recorte precisa significar a mesma coisa para todo mundo
 * e bater com o que o servidor usa: `in_last_days`/`not_in_last_days` contam dias de calendário em
 * America/Sao_Paulo (ver supabase/migrations/20261002391230_talkx_audience_rpc.sql), assim como
 * `conversation_closure_day` e os filtros de segmento (`SEGMENT_TIMEZONE`).
 */
const PERIOD_TIMEZONE = 'America/Sao_Paulo';

/**
 * Início do recorte de período da telemetria, como instante ISO.
 *
 * "1h"/"6h"/"24h" são janelas **corridas** (o rótulo promete horas: "Últimas 24h"). "7d" é um
 * recorte em **dias de calendário** — hoje + 6 anteriores, o mesmo recorte do R3-06 na timeline
 * do Histórico. Antes eram 168 h corridas: às 22h30 em São Paulo o período alcançava o 8º dia.
 *
 * O "7d" é ancorado em America/Sao_Paulo, não no fuso do navegador: com o fuso do navegador o
 * mesmo filtro "últimos 7 dias" recortava janelas diferentes para pessoas em fusos diferentes e
 * nunca coincidia com o recorte que o servidor aplica.
 */
export function periodStartIso(timeFilter: TimeFilter, now: Date = new Date()): string {
  const horasCorridas: Partial<Record<TimeFilter, number>> = { "1h": 1, "6h": 6, "24h": 24 };
  const horas = horasCorridas[timeFilter];
  if (horas) return new Date(now.getTime() - horas * 3_600_000).toISOString();
  return zonedDayStartISO(PERIOD_TIMEZONE, 6, now);
}
